@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<div class="stepper mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "pending";

            <div class="step-item text-center flex-fill @status"
                 style="cursor: @(step < CurrentStep ? "pointer" : "default")"
                 @onclick="() => OnStepClicked(step)">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle
                            @(status == "completed" ? "bg-success text-white" :
                              status == "active" ? "bg-primary text-white" :
                              "bg-light text-muted border")"
                     style="width:36px;height:36px;font-size:0.85rem;">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="d-none d-sm-block @(status == "pending" ? "text-muted" : "")">
                    @StepNames[step]
                </small>
            </div>
        }
    </div>
</div>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
            await OnNavigateToStep.InvokeAsync(step);
    }
}

@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label">Full Name <span class="text-danger">*</span></label>
    <input class="form-control" @bind="Model.FullName" @bind:event="oninput" />
</div>

<div class="mb-3">
    <label class="form-label">Email <span class="text-danger">*</span></label>
    <input type="email" class="form-control @(EmailError is not null ? "is-invalid" : "")"
           @bind="Model.Email" @bind:event="oninput" />
    @if (EmailError is not null)
    {
        <div class="invalid-feedback">@EmailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label">Phone <span class="text-danger">*</span></label>
    <input type="tel" class="form-control" @bind="Model.Phone" @bind:event="oninput" />
</div>

<div class="mb-3">
    <label class="form-label">Address <span class="text-danger">*</span></label>
    <textarea class="form-control" rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
</div>

@if (ValidationMessage is not null)
{
    <div class="alert alert-danger py-2">@ValidationMessage</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ValidationMessage;
    private string? EmailError;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ValidationMessage = null;
        EmailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ValidationMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ValidateEmail(Model.Email);
            if (!emailValid)
            {
                EmailError = "Please enter a valid email address.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Company" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Title" @bind:event="oninput" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input type="checkbox" class="form-check-input" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (ValidationMessage is not null)
{
    <div class="alert alert-danger py-2">@ValidationMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public WorkHistoryModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void AddEntry()
    {
        Model.Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Model.Entries.Count > 1)
            Model.Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        foreach (var entry in Model.Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ValidationMessage = "Company, job title, and start date are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">References</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Name" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Relationship" @bind:event="oninput" />
