@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<div class="stepper mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var status = step < CurrentStep ? "completed"
                       : step == CurrentStep ? "active"
                       : "pending";

            <div class="step-item text-center flex-fill @status"
                 style="cursor: @(step < CurrentStep ? "pointer" : "default")"
                 @onclick="() => OnStepClicked(step)">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle
                            @(status == "completed" ? "bg-success text-white" :
                              status == "active" ? "bg-primary text-white" :
                              "bg-light text-muted border")"
                     style="width:36px;height:36px;font-size:0.85rem;">
                    @if (status == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="d-none d-sm-block @(status == "pending" ? "text-muted" : "")">
                    @StepNames[step]
                </small>
            </div>
        }
    </div>
</div>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnNavigateToStep { get; set; }

    private async Task OnStepClicked(int step)
    {
        if (step < CurrentStep)
            await OnNavigateToStep.InvokeAsync(step);
    }
}

@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">Personal Information</h4>

