@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Company" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Title" @bind:event="oninput" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate" disabled="@entry.IsCurrent" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input type="checkbox" class="form-check-input" id="current-@index"
                               @bind="entry.IsCurrent" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" @bind="entry.Description" @bind:event="oninput"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (ValidationMessage is not null)
{
    <div class="alert alert-danger py-2">@ValidationMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public WorkHistoryModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void AddEntry()
    {
        Model.Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Model.Entries.Count > 1)
            Model.Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        foreach (var entry in Model.Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ValidationMessage = "Company, job title, and start date are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply

<h4 class="mb-3">References</h4>

@for (int i = 0; i < Model.Entries.Count; i++)
{
    var index = i;
    var entry = Model.Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (Model.Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Name" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input class="form-control" @bind="entry.Relationship" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="entry.Email" @bind:event="oninput" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="entry.Phone" @bind:event="oninput" />
                </div>
            </div>
        </div>
    </div>
}

@if (Model.Entries.Count < 3)
{
    <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Reference
    </button>
}

@if (ValidationMessage is not null)
{
    <div class="alert alert-danger py-2">@ValidationMessage</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter] public ReferencesModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ValidationMessage;

    private void AddEntry()
    {
        if (Model.Entries.Count < 3)
            Model.Entries.Add(new ReferenceEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Model.Entries.Count > 1)
            Model.Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        ValidationMessage = null;

        if (Model.Entries.Count < 2)
        {
            ValidationMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var entry in Model.Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Name) ||
                string.IsNullOrWhiteSpace(entry.Relationship) ||
                string.IsNullOrWhiteSpace(entry.Email) ||
                string.IsNullOrWhiteSpace(entry.Phone))
            {
                ValidationMessage = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

