+                    <label class="form-label">Name <span class="text-danger">*</span></label>
+                    <input class="form-control" @bind="entry.Name" @bind:event="oninput" />
+                </div>
+                <div class="col-md-6">
+                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
+                    <input class="form-control" @bind="entry.Relationship" @bind:event="oninput" />
+                </div>
+                <div class="col-md-6">
+                    <label class="form-label">Email <span class="text-danger">*</span></label>
+                    <input type="email" class="form-control" @bind="entry.Email" @bind:event="oninput" />
+                </div>
+                <div class="col-md-6">
+                    <label class="form-label">Phone <span class="text-danger">*</span></label>
+                    <input type="tel" class="form-control" @bind="entry.Phone" @bind:event="oninput" />
+                </div>
+            </div>
