namespace sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply;

/// <summary>
/// Mutable view-models backing each wizard step.
/// Converted to immutable records on submission.
/// </summary>
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";
}

public class WorkHistoryModel
{
    public List<WorkEntryModel> Entries { get; set; } = [new()];
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";
}

public class ReferencesModel
{
    public List<ReferenceEntryModel> Entries { get; set; } = [new(), new()];
}

public class ReferenceEntryModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
}

public class CoverLetterModel
{
    public string CoverLetter { get; set; } = "";
}

