arguments.file_text:
@page "/apply"
@rendermode InteractiveServer

@using sv_6bdf726f70f5408fadfcdf6c8ae44d19.Components.Pages.Apply
@using sv_6bdf726f70f5408fadfcdf6c8ae44d19.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep" OnNavigateToStep="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@_personal"
                              OnNext="NextStep"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Model="@_workHistory"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep Model="@_references"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep Model="@_coverLetter"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@_personal"
                        WorkHistory="@_workHistory"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnBack="PreviousStep"
                        OnEditStep="GoToStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    private int _currentStep;

    private readonly PersonalInfoModel _personal = new();
    private readonly WorkHistoryModel _workHistory = new();
    private readonly ReferencesModel _references = new();
    private readonly CoverLetterModel _coverLetter = new();

    private void NextStep() => _currentStep++;
    private void PreviousStep() => _currentStep--;
    private void GoToStep(int step) => _currentStep = step;

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            new PersonalInfo(_personal.FullName, _personal.Email, _personal.Phone, _personal.Address),
            new WorkHistory(_workHistory.Entries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList()),
            _references.Entries.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList(),
            _coverLetter.CoverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

